planner_namespace.actual_init_shutdown_state_reset_stateme:
static void epoch_state_init(void)
{
	memset(&H, 0, sizeof H);
}
static void epoch_state_shutdown(void)
{
	memset(&H, 0, sizeof H);
}
static void epoch_tick_frames(u32 count) { while (count--) { H.frame_no++; plan_advance(1u); } }
static void epoch_fixture_clock_init(void) { plan_clock = 1; }
static int epoch_hint_live(const GLMipmap_t *k) { return k->ps2_ihfr && plan_stamp() - k->ps2_ihfr <= 2; }

static void epoch_wrap_test(void)
{
    unsigned failures = 0, cases = 0;
    plan_info_p = calloc(1, sizeof *plan_info_p);
    if (!plan_info_p) exit(11);
    for (u32 offset = 0; offset <= 160; offset++)
    {
        GLMipmap_t m;
        int visible;
        u32 old;
        memset(&m, 0, sizeof m);
        plan_clock = ~0u - offset;
        old = plan_stamp();
        plan_advance(1u);
        failures += !old || !plan_stamp() || plan_stamp() - old < 1u || plan_stamp() - old > 2u;
        cases++;
        plan_clock = old;
        m.ps2_planfr = m.ps2_full_fr = m.ps2_ihfr = old;
        plan_reset();
        failures += !plan_stamp() || plan_stamp() - old < PLAN_FULL_KEEP;
        failures += plan_key(&m) == NULL;
        m.ps2_want = 3; m.ps2_vis = 1; batch_phase = 2;
        failures += epoch_tex_want(&m, &visible) != 3 || epoch_hint_live(&m);
        cases++;
    }
    free(plan_info_p);
    printf("HIGHRES WRAP tested=1 failures=%u cases=%u\n", failures, cases);
}

